using System;
using System.Collections;
using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PrecisionAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Precision Action")]
public class PrecisionAction : ChooseDiceAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private GameObject precisionPanelPrefab;

	[SerializeField]
	private CameraReference dicePreviewCameraReference;

	[Header("Dice Rotation Animation")]
	[SerializeField]
	private float diceRotationAnimationDuration;

	[SerializeField]
	private AnimationCurve diceRotationAnimationCurve;

	[Header("Debug")]
	[SerializeField]
	private bool precisionDiceDebug;

	[Header("Precision Action Workaround")]
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	[NonSerialized]
	private DicePreviewPrecisionActionCanvas precisionPanel;

	public Action SandsOfTimePrecisionAction;

	private GameStateManager gameStateManager => ReferenceSingleton<GameStateManager>.Instance;

	public void SetPrecisionActionPlayed()
	{
		playerEffectsList.SandsOfTimeEffect.PrecisionActionPlayed = true;
	}

	public override void Cast(GameObject source)
	{
		if (precisionDiceDebug)
		{
			(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance).DestroyDiceDisposeAction();
		}
		gameStateManager.TryEnterNoInteractionState();
		SetPrecisionActionPlayed();
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(PrecisionActionCoroutine());
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		});
	}

	private IEnumerator PrecisionActionCoroutine()
	{
		bool flag = false;
		if (!ReferenceSingleton<BattleHandler>.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive())
		{
			flag = true;
		}
		if (diceList[0].DiceOwnerEnum != 0 && diceList[0].ActionOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			flag = true;
		}
		if (!flag)
		{
			gameStateManager.SetState(gameStateManager.PrecisionActionState);
			yield return InvokeAlternatives.WaitOneFrame();
			diceList[0].DiceVisuals.SetNoOutlineLayer();
			GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(precisionPanelPrefab.name);
			if (@object == null)
			{
				ReferenceSingleton<PoolHandler>.Instance.AddPool(precisionPanelPrefab);
				@object = ReferenceSingleton<PoolHandler>.Instance.GetObject(precisionPanelPrefab.name);
				@object.GetComponent<Canvas>().worldCamera = dicePreviewCameraReference.value;
			}
			if (precisionPanel == null)
			{
				precisionPanel = @object.GetComponent<DicePreviewPrecisionActionCanvas>();
			}
			precisionPanel.ShowDiceFaceChoosePanel(diceList[0], this);
		}
	}

	public void DiceFaceChosen(DiceFace diceFace)
	{
		diceList[0].RotateToDiceFace(diceFace, diceRotationAnimationDuration, diceRotationAnimationCurve);
		ReferenceSingleton<CoroutineHandler>.Instance.Run(DiceFaceChosenCoroutine());
	}

	private IEnumerator DiceFaceChosenCoroutine()
	{
		precisionPanel.HideDiceFaceChoosePanel();
		yield return new WaitForSeconds(diceRotationAnimationDuration);
		diceList[0].GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, delegate
		{
			diceList[0].UpdateDiceFace();
			ResetVariables();
			if (playerEffectsList.SandsOfTimeEffect.SandsOfTimeTriggered)
			{
				if (SandsOfTimePrecisionAction != null)
				{
					SandsOfTimePrecisionAction();
				}
				else if (!gameStateManager.ActionsQueueState.IsAnyActionOnQueuesOrAnyActionsExecuting())
				{
					gameStateManager.SetChooseActionState();
				}
				else
				{
					gameStateManager.SetActionsQueueState();
				}
			}
			else if (!gameStateManager.ActionsQueueState.IsAnyActionOnQueuesOrAnyActionsExecuting())
			{
				gameStateManager.SetChooseActionState();
			}
			else
			{
				gameStateManager.SetActionsQueueState();
			}
			playerEffectsList.SandsOfTimeEffect.PrecisionActionPlayed = false;
		});
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
	}
}
